@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('#narcotics-list');const add=document.querySelector('[data-add-narcotic]');if(!list||!add)return;let index=list.querySelectorAll('.narcotic-row').length;const updateClonedRow=(row)=>{row.querySelectorAll('input,select').forEach((field)=>{field.name=field.name.replace(/narcotics\[\d+\]/,`narcotics[${index}]`);field.value='';});row.querySelectorAll('[data-custom-select]').forEach((root)=>{delete root.dataset.customSelectInitialized;root.dataset.selectName=root.querySelector('select')?.name??root.dataset.selectName;root.querySelectorAll('[id]').forEach((element)=>{element.id=element.id.replace(/narcotics-\d+-/,`narcotics-${index}-`);});root.querySelectorAll('[for],[aria-controls],[aria-labelledby],[aria-activedescendant]').forEach((element)=>{['for','aria-controls','aria-labelledby','aria-activedescendant'].forEach((attribute)=>{const value=element.getAttribute(attribute);if(value)element.setAttribute(attribute,value.replace(/narcotics-\d+-/,`narcotics-${index}-`));});});});};add.addEventListener('click',()=>{const template=list.querySelector('.narcotic-row');if(!template)return;const row=template.cloneNode(true);updateClonedRow(row);list.appendChild(row);window.initializeCustomSelects?.(row);index++;});list.addEventListener('click',(event)=>{if(event.target.matches('[data-remove-narcotic]')&&list.querySelectorAll('.narcotic-row').length>1)event.target.closest('.narcotic-row').remove();});});</script>@endpush
